//-------------------------------------------------------------------------------------------------
//  Local Defines
//-------------------------------------------------------------------------------------------------
#define SCRIPT_BUF_FOR_DO_MSTAR 4096
#define ARG_NUM_SCRIPT_FILE         1
#define IS_ARG_AVAILABLE_SCRIPT_FILE(x) ((x) > ARG_NUM_SCRIPT_FILE)
#define DEFAULT_SCRIPT_FILE_NAME    "auto_update.txt"   // script file name
#define ARG_SCRIPT_FILE(x)              (x)[ARG_NUM_SCRIPT_FILE]


int do_scriptstar (cmd_tbl_t *cmdtp, int flag, int argc, char * const argv[])
{
    char* buffer = NULL;
    char cmd_buffer[CMD_BUF] = {0};
    char *script_buf = NULL;
    char *next_line = NULL;
    char *ScriptFile = NULL;
    unsigned long iFilesize = 0;
    char *tmp = NULL;
    int BeAbort = 1;
    int snprintf_len;

    UBOOT_TRACE("IN\n");

    ScriptFile= IS_ARG_AVAILABLE_SCRIPT_FILE(argc) ? ARG_SCRIPT_FILE(argv) : DEFAULT_SCRIPT_FILE_NAME;
    UBOOT_DEBUG("ScriptFile=%s\n",ScriptFile);

    buffer=(char *)malloc(SCRIPT_BUF_FOR_DO_MSTAR);
    if (buffer == NULL)
    {
        UBOOT_ERROR("ERROR: Failed to allocate 0x%x bytes.\n",SCRIPT_BUF_FOR_DO_MSTAR);
        return -1;
    }
    // Set mstar commmand abort or not when cmd error.
    tmp = env_get ("CmdAbort");
    if (tmp != NULL)
    {
        BeAbort = (int)simple_strtol(tmp, NULL, 10);
        UBOOT_DEBUG("BeAbort=%d\n",BeAbort);
    }

    // Load script
    memset(buffer, 0 , SCRIPT_BUF_FOR_DO_MSTAR);
    memset(cmd_buffer, 0 , CMD_BUF);
    snprintf_len = snprintf(cmd_buffer, CMD_BUF, "tftp %p %s", buffer,ScriptFile);
    if (snprintf_len >= CMD_BUF)
    {
        UBOOT_ERROR("The array size is too small(%d), snprintf fail '%s'\n", CMD_BUF, cmd_buffer);
        free(buffer);
        return -1;
    }
    UBOOT_DEBUG("cmd=%s\n",cmd_buffer);
    if(0 != run_command(cmd_buffer, 0))
    {
        UBOOT_ERROR("cmd: %s\n",cmd_buffer);
        free(buffer);
        return -1;
    }


    // Run script
    iFilesize = (unsigned long)simple_strtol(env_get("filesize"), NULL, 16);
    UBOOT_DEBUG("iFilesize=0x%lx\n",iFilesize);
    script_buf = buffer;
    script_buf[iFilesize]='\n'; script_buf[iFilesize+1]='%';
    while ((next_line = get_script_next_line(&script_buf)) != NULL)
    {
        next_line = para_replace(next_line, (argc-2), &argv[1]);
        UBOOT_INFO ("\n>> %s \n", next_line);
        if(0 != run_command(next_line, 0))
        {
            UBOOT_ERROR("command error!\n");
            if(BeAbort == 1)
            {
                free(buffer);
                return -1;
            }
        }
    }
    free(buffer);
    UBOOT_TRACE("OK\n");
    return 0;
}

U_BOOT_CMD(
    scriptstar ,    2,    0,     do_scriptstar,
    "update kernal & root file system automatically by script file",
    "scriptstar [script_file_name]\n"
    "set CmdAbort = 0 in env to ignore the abort when cmd error\n"
);

int do_del_boogargs (cmd_tbl_t *cmdtp, int flag, int argc, char * const argv[])
{
   int ret;
   UBOOT_TRACE("IN\n");
   if(argc!=2)
   {
        return cmd_usage(cmdtp);
   }

   ret = del_bootargs(argv[1],1);
   if(ret==0)
   {
        UBOOT_TRACE("OK\n");
   }
   else
   {
        UBOOT_ERROR("delete %s fail\n",argv[1]);
   }
   return ret;
}


U_BOOT_CMD(
    deletebootargs, 2, 0, do_del_boogargs,
    "delete the specific cofig that is in the bootargs\n",
    "[config]\n"
    "For example: deleteBootargs autotest\n"
);

int do_add_bootargs (cmd_tbl_t *cmdtp, int flag, int argc, char * const argv[])
{
   int ret;
   unsigned int prefixLen=0;
   unsigned int contentLen=0;
   char *buffer=NULL;
   int snprintf_len;
   UBOOT_TRACE("IN\n");
   if(argc!=3)
   {
        return cmd_usage(cmdtp);
   }
   prefixLen=strlen(argv[1]);
   contentLen=strlen(argv[2]);
   //2? for '=' and the end symbol
   #define BUFFER_SIZE (prefixLen+contentLen+2)
   buffer=malloc(BUFFER_SIZE);
   if(buffer==NULL)
   {
       UBOOT_ERROR("malloc fail\n");
       return -1;
   }
   printf(" argv[1]%s \n",argv[1]);
   printf(" argv[2]%s \n",argv[2]);
   snprintf_len = snprintf(buffer,BUFFER_SIZE,"%s=%s",argv[1],argv[2]);
   if (snprintf_len >= BUFFER_SIZE)
   {
       UBOOT_ERROR("The array size is too small(%d), snprintf fail '%s'\n", BUFFER_SIZE, buffer);
       free(buffer);
       return -1;
   }
   UBOOT_DEBUG("buffer: %s\n",buffer);
   ret = add_bootargs(argv[1],buffer,1);
   if(ret==0)
   {
        UBOOT_TRACE("OK\n");
   }
   else
   {
        UBOOT_ERROR("delete %s fail\n",argv[1]);
   }
   free(buffer);
   #undef BUFFER_SIZE
   return ret;
}

U_BOOT_CMD(
    addbootargs, 3, 0, do_add_bootargs,
    "set a new config to the bootargs\n",
    "[config][content]\n"
    "For example: addBootargs autotest true\n"
);

int do_add_version2bootargs(cmd_tbl_t *cmdtp, int flag, int argc, char * const argv[])
{
   int ret=0;
   char cmd_buffer[256] = {0};
   int snprintf_len;
   memset(cmd_buffer, 0 , 256);
   snprintf_len = snprintf(cmd_buffer, 256, "addbootargs androidboot.bootloader %s", U_BOOT_VERSION);
   if (snprintf_len >= 256)
   {
       UBOOT_ERROR("The array size is too small(%d), snprintf fail '%s'\n", 256, cmd_buffer);
       return -1;
   }
   printf("cmd=%s\n",cmd_buffer);
   if(0 != run_command(cmd_buffer, 0))
   {
       UBOOT_ERROR("cmd: %s\n",cmd_buffer);
       ret= -1;
   }

   return ret;
}

U_BOOT_CMD(
    addversion, 1, 0, do_add_version2bootargs,
    "set a uboot version to the bootargs\n",
    " \n"
    "For example: addVersion \n"
);


