int do_set_retry_count(cmd_tbl_t *cmdtp, int flag, int argc, char * const argv[])
{
    int ret=0;
    unsigned int retry_count = 0;

    if (argc != 2)
    {
        return CMD_RET_USAGE;
    }
    retry_count = simple_strtoul(argv[1], NULL, 10);
    if(retry_count>3)
    {
        return CMD_RET_USAGE;
    }
    sys_set_retry_count(retry_count);
    return ret;
}

